import { z } from 'zod';
import { SourceSyncModeSchema } from './source-sync';
import {
  GuidanceOriginSchema,
  GuidanceSyncStatusSchema,
} from './guidance-source';
import {
  GuidanceVerifierSchema,
  GuidanceVerifierSummarySchema,
  isSeparateVerifierUpdate,
} from './guidance-verifier';
import {
  GuidanceReferencesSchema,
  GuidanceReferencesUploadSchema,
} from './guidance-references';
import {
  ProfileMediaSchema,
  PROFILE_UPLOAD_COUNT,
  PROFILE_UPLOAD_ENCODED_BYTES,
} from './design-profile';

const LARGE_GUIDANCE_BYTES = 32 * 1024;
const GUIDANCE_TITLE_LENGTH = 500;
const GUIDANCE_ID_LENGTH = 200;
export const GUIDANCE_IMAGE_BYTES = 10 * 1024 * 1024;
export const GuidanceAttachmentSchema = ProfileMediaSchema.extend({
  source: z.string().min(1),
  alt: z.string(),
  title: z.string().optional(),
  path: z.string().min(1),
});
export type GuidanceAttachment = z.infer<typeof GuidanceAttachmentSchema>;
const GuidanceImagesSchema = z
  .array(
    z
      .object({
        source: z.string().min(1),
        dataUrl: z.string().max(PROFILE_UPLOAD_ENCODED_BYTES),
      })
      .strict(),
  )
  .max(PROFILE_UPLOAD_COUNT);

export const guidanceByteLength = (markdown: string): number =>
  new TextEncoder().encode(markdown).byteLength;

const GuidanceIdSchema = z.string().min(1).max(GUIDANCE_ID_LENGTH);
const GuidanceMarkdownSchema = z
  .string()
  .refine((value) => value.trim().length > 0, 'Guidance must contain text');

export const GuidanceDocumentSchema = z
  .object({
    id: GuidanceIdSchema,
    title: z.string().trim().min(1).max(GUIDANCE_TITLE_LENGTH),
    markdown: GuidanceMarkdownSchema,
    attachments: z.array(GuidanceAttachmentSchema).optional(),
    references: GuidanceReferencesSchema.optional(),
    origin: GuidanceOriginSchema.optional(),
  })
  .strict();
export const SavedGuidanceSchema = GuidanceDocumentSchema.extend({
  isEnabled: z.boolean(),
  verifier: GuidanceVerifierSummarySchema.optional(),
  sync: GuidanceSyncStatusSchema.optional(),
  syncMode: SourceSyncModeSchema.optional(),
});
export const GuidanceInputSchema = SavedGuidanceSchema.omit({
  id: true,
  verifier: true,
  syncMode: true,
}).extend({
  isEnabled: z.boolean().default(true),
});
export const GuidanceUpdateSchema = SavedGuidanceSchema.omit({
  id: true,
  verifier: true,
  syncMode: true,
})
  .partial()
  .extend({
    verifier: GuidanceVerifierSchema.nullable().optional(),
    origin: GuidanceOriginSchema.nullable().optional(),
    sync: GuidanceSyncStatusSchema.nullable().optional(),
  })
  .refine(
    isSeparateVerifierUpdate,
    'Update source content and verifier separately',
  )
  .refine(
    (value) => Object.keys(value).length > 0,
    'Provide a guidance update',
  );
export const GuidanceUploadSchema = GuidanceInputSchema.omit({
  attachments: true,
  references: true,
  origin: true,
  sync: true,
})
  .extend({
    images: GuidanceImagesSchema.optional(),
    references: GuidanceReferencesUploadSchema.optional(),
  })
  .strict();
export const GuidanceUploadUpdateSchema = GuidanceUploadSchema.partial()
  .extend({
    isEnabled: z.boolean().optional(),
    verifier: GuidanceVerifierSchema.nullable().optional(),
  })
  .refine(
    isSeparateVerifierUpdate,
    'Update source content and verifier separately',
  )
  .refine(
    (value) =>
      Object.keys(value).length > 0 &&
      (value.images === undefined || value.markdown !== undefined),
    'Provide a guidance update; image uploads require Markdown',
  );
export type GuidanceUpload = z.input<typeof GuidanceUploadSchema>;
export type GuidanceUploadUpdate = z.infer<typeof GuidanceUploadUpdateSchema>;
export const GuidanceSelectionSchema = z
  .object({
    mode: z.enum(['auto', 'off']).default('auto'),
    excludedIds: z.array(GuidanceIdSchema).default([]),
  })
  .strict()
  .refine(
    (value) => value.mode !== 'off' || value.excludedIds.length === 0,
    'Guidance off cannot be combined with exclusions',
  );

export type GuidanceDocument = z.infer<typeof GuidanceDocumentSchema>;
export type SavedGuidance = z.infer<typeof SavedGuidanceSchema>;
export type GuidanceInput = z.input<typeof GuidanceInputSchema>;
export type GuidanceUpdate = z.infer<typeof GuidanceUpdateSchema>;
export type GuidanceSelection = z.infer<typeof GuidanceSelectionSchema>;
export type GuidanceErrorCode =
  | 'guidance_not_found'
  | 'guidance_account_changed'
  | 'guidance_auth_required'
  | 'guidance_asset_invalid'
  | 'guidance_source_unavailable'
  | 'guidance_source_changed';

export class GuidanceError extends Error {
  constructor(
    readonly code: GuidanceErrorCode,
    message: string,
  ) {
    super(message);
    this.name = 'GuidanceError';
  }
}

export const guidancePayloadByteLength = (
  documents: GuidanceDocument[],
): number => guidanceByteLength(JSON.stringify(documents));

export const GuidanceWarningSchema = z.object({
  code: z.literal('large_saved_context'),
  documentCount: z.number().int().nonnegative(),
  byteCount: z.number().int().nonnegative(),
  message: z.string(),
});

export type GuidanceWarning = z.infer<typeof GuidanceWarningSchema>;

export const guidanceWarning = (
  documents: readonly GuidanceDocument[],
): GuidanceWarning | undefined => {
  const byteCount = documents.reduce(
    (total, document) =>
      total +
      guidanceByteLength(document.markdown) +
      (document.references ?? []).reduce(
        (bytes, reference) =>
          bytes +
          guidanceByteLength(reference.intent) +
          (reference.kind === 'directory'
            ? []
            : (reference.files ?? [])
          ).reduce((size, file) => size + guidanceByteLength(file.content), 0),
        0,
      ),
    0,
  );
  if (byteCount <= LARGE_GUIDANCE_BYTES) return undefined;
  return {
    code: 'large_saved_context',
    documentCount: documents.length,
    byteCount,
    message: `Saved context includes ${documents.length} ${documents.length === 1 ? 'document' : 'documents'} and ${byteCount} UTF-8 bytes of guidance and reference text. Native reference files are available for workers to read. This may use substantial prompt space; bytes do not predict model capacity. To reduce it for a run, choose documents to exclude or use --guidance off.`,
  };
};
